"id": "TagsDetail",
"type": "object",
"description": "Used for filtering messages by tag in various methods. Note that functions using this type may have a partial implementation.",
"properties": {
  "tags": {
    "type": "object",
    "description": "A <em>dictionary object</em> with one or more filter condition as <em>key-value</em> pairs, the <em>key</em> being the tag to filter on, and the <em>value</em> being a boolean expression, requesting whether a message must include (<var>true</var>) or exclude (<var>false</var>) the tag. For a list of available tags, call the $(ref:messages.tags.list) method.",
    "patternProperties": {
      ".*": {
        "type": "boolean"
      }
    }
  },
  "mode": {
    "type": "string",
    "description": "Whether <var>all</var> of the tag filters must apply, <var>any</var> of them, or <var>none</var>. The <var>none</var> mode ignores the provided filters and selects only messages without any tags.",
    "enum": ["all", "any", "none"]
  }
}
